SELECT 
FROM et_comment

    comment_id = #{commentId}
    AND question_id = #{questionId}
    AND comment_index = #{indexId}
    AND user_id = #{userId}
    AND quote_id = #{quoteId}
    AND re_id = #{reId}

        AND content_msg LIKE CONCAT('%', #{contentMsg}, '%')


ORDER BY create_time DESC

SELECT 
FROM et_comment

    comment_id = #{condition.commentId}
    AND question_id = #{condition.questionId}
    AND comment_index = #{condition.indexId}
    AND user_id = #{condition.userId}
    AND quote_id = #{condition.quoteId}
    AND re_id = #{condition.reId}

        AND content_msg LIKE CONCAT('%', #{condition.contentMsg}, '%')


ORDER BY create_time DESC
LIMIT #{offset}, #{pageSize}

